261: 		if (_getbit(bmp1, i) != _getbit(bmp2, i))
262: 			return 0;
263: 	return 1;
264: }
265: 
266: /* Hamming Weight: number of set bits */
267: unsigned int numa_bitmask_weight(const struct bitmask *bmp)
268: {
269: 	unsigned int i;
270: 	unsigned int w = 0;
271: 	for (i = 0; i < bmp->size; i++)
272: 		if (_getbit(bmp, i))
273: 			w++;
274: 	return w;
275: }
