356: /*
357:  * Find nodes (numa_nodes_ptr), nodes with memory (numa_memnode_ptr)
358:  * and the highest numbered existing node (maxconfigurednode).
359:  */
360: static void
361: set_configured_nodes(void)
362: {
363: 	DIR *d;
364: 	struct dirent *de;
365: 
366: 	numa_memnode_ptr = numa_allocate_nodemask();
367: 	numa_nodes_ptr = numa_allocate_nodemask();
368: 	if (!numa_memnode_ptr || !numa_nodes_ptr)
369: 		return;
