512: /*
513:  * Read a processes constraints in terms of nodes and cpus from
514:  * /proc/self/status.
515:  */
516: static void
517: set_task_constraints(void)
518: {
519: 	int hicpu = maxconfiguredcpu;
520: 	int i;
521: 	char *buffer = NULL;
522: 	size_t buflen = 0;
523: 	FILE *f;
524: 
525: 	numa_all_cpus_ptr = numa_allocate_cpumask();
526: 	numa_possible_cpus_ptr = numa_allocate_cpumask();
527: 	numa_all_nodes_ptr = numa_allocate_nodemask();
528: 	numa_possible_nodes_ptr = numa_allocate_cpumask();
529: 	numa_no_nodes_ptr = numa_allocate_nodemask();
530: 
531: 	// partial leak shouldn't happen because its transient
532: 	if (!numa_all_cpus_ptr || !numa_possible_cpus_ptr ||
533: 		!numa_all_nodes_ptr ||
534: 		!numa_possible_nodes_ptr ||
535: 		!numa_no_nodes_ptr)
536: 		return;
537: 
538: 	f = fopen(mask_size_file, "r");
539: 	if (!f) {
540: 		//numa_warn(W_cpumap, "Cannot parse %s", mask_size_file);
541: 		return;
542: 	}
543: 
544: 	while (getline(&buffer, &buflen, f) > 0) {
545: 		/* mask starts after [last] tab */
546: 		char  *mask = strrchr(buffer,'\t') + 1;
547: 
548: 		if (strncmp(buffer,"Cpus_allowed:",13) == 0)
549: 			numproccpu = read_mask(mask, numa_all_cpus_ptr);
550: 
551: 		if (strncmp(buffer,"Mems_allowed:",13) == 0) {
552: 			numprocnode = read_mask(mask, numa_all_nodes_ptr);
553: 		}
554: 	}
555: 	fclose(f);
556: 	free(buffer);
557: 
558: 	for (i = 0; i <= hicpu; i++)
559: 		numa_bitmask_setbit(numa_possible_cpus_ptr, i);
560: 	for (i = 0; i <= maxconfigurednode; i++)
561: 		numa_bitmask_setbit(numa_possible_nodes_ptr, i);
562: 
563: 	/*
564: 	 * Cpus_allowed in the kernel can be defined to all f's
565: 	 * i.e. it may be a superset of the actual available processors.
566: 	 * As such let's reduce numproccpu to the number of actual
567: 	 * available cpus.
568: 	 */
569: 	if (numproccpu <= 0) {
570: 		for (i = 0; i <= hicpu; i++)
571: 			numa_bitmask_setbit(numa_all_cpus_ptr, i);
572: 		numproccpu = hicpu+1;
573: 	}
574: 
575: 	if (numproccpu > hicpu+1) {
576: 		numproccpu = hicpu+1;
577: 		for (i=hicpu+1; i<numa_all_cpus_ptr->size; i++) {
578: 			numa_bitmask_clearbit(numa_all_cpus_ptr, i);
579: 		}
580: 	}
581: 
582: 	if (numprocnode <= 0) {
583: 		for (i = 0; i <= maxconfigurednode; i++)
584: 			numa_bitmask_setbit(numa_all_nodes_ptr, i);
585: 		numprocnode = maxconfigurednode + 1;
586: 	}
587: 
588: 	return;
589: }
