642: set_preferred_many(void)
643: {
644: 	int oldp;
645: 	struct bitmask *bmp, *tmp;
646: 	int old_errno;
647: 
648: 	if (has_preferred_many >= 0)
649: 		return;
650: 
651: 	old_errno = errno;
652: 
653: 	has_preferred_many = 0;
654: 
655: 	bmp = numa_allocate_nodemask();
656: 	tmp = numa_get_mems_allowed();
657: 	if (!tmp || !bmp)
658: 		goto out;
659: 
660: 	if (get_mempolicy(&oldp, bmp->maskp, bmp->size, 0, 0) < 0)
661: 		goto out;
662: 
663: 	if (set_mempolicy(MPOL_PREFERRED_MANY, tmp->maskp, tmp->size) == 0) {
664: 		has_preferred_many = 1;
665: 		/* reset the old memory policy ignoring error */
666: 		(void)set_mempolicy(oldp, bmp->maskp, bmp->size+1);
667: 	}
668: 
669: out:
670: 	numa_bitmask_free(tmp);
671: 	numa_bitmask_free(bmp);
672: 	errno = old_errno;
673: }
