182: 		show_physcpubind();
183: 		printf("No NUMA support available on this system.\n");
184: 		exit(1);
185: 	}
186: 
187: 	cpubind = numa_get_run_node_mask();
188: 
189: 	preferred = numa_preferred_many();
190: 	interleave = numa_get_interleave_mask();
191: 	weighted_interleave = numa_get_weighted_interleave_mask();
192: 	membind = numa_get_membind();
193: 	cur = numa_get_interleave_node();
194: 
195: 	policy = 0;
196: 	if (get_mempolicy(&policy, NULL, 0, 0, 0) < 0)
197: 		perror("get_mempolicy");
198: 
199: 	printf("policy: %s\n", policy_name(policy));
200: 
201: 	printf("preferred node: ");
202: 	switch (policy) {
203: 	case MPOL_PREFERRED:
204: 		if (numa_bitmask_weight(preferred))
205: 			printf("%d\n", find_first(preferred));
206: 		else
207: 			printf("%d\n", 0);
208: 		break;
209: 	case MPOL_DEFAULT:
210: 		printf("current\n");
211: 		break;
212: 	case MPOL_INTERLEAVE:
213: 	case MPOL_WEIGHTED_INTERLEAVE:
214: 		printf("%ld (interleave next)\n",cur);
215: 		break;
216: 	case MPOL_BIND:
217: 		printf("%d\n", find_first(membind));
218: 		break;
219: 	case MPOL_PREFERRED_MANY:
220: 		printf("%ld (preferred-many)\n",cur);
221: 		break;
222: 	}
223: 	if (policy == MPOL_INTERLEAVE) {
224: 		printmask("interleavemask", interleave);
225: 		printf("interleavenode: %ld\n", cur);
226: 	} else if (policy == MPOL_WEIGHTED_INTERLEAVE) {
227: 		printmask("interleavemask", weighted_interleave);
228: 		show_weighted_interleave_weights();
229: 		printf("interleavenode: %ld\n", cur);
230: 	}
231: 	show_physcpubind();
232: 	printmask("cpubind", cpubind);  // for compatibility
233: 	printmask("nodebind", cpubind);
234: 	printmask("membind", membind);
235: 	printmask("preferred", preferred);
236: 	numa_bitmask_free(cpubind);
237: 	numa_bitmask_free(membind);
238: 	numa_bitmask_free(preferred);
239: 	numa_bitmask_free(interleave);
240: 	numa_bitmask_free(weighted_interleave);
241: }
