252: static void print_distances(int maxnode)
253: {
254: 	int i,k;
255: 	int fst = 0;
256: 
257: 	for (i = 0; i <= maxnode; i++)
258: 		if (numa_bitmask_isbitset(numa_nodes_ptr, i)) {
259: 			fst = i;
260: 			break;
261: 		}
262: 	if (numa_distance(maxnode,fst) == 0) {
263: 		printf("No distance information available.\n");
264: 		return;
265: 	}
266: 	printf("node distances:\n");
267: 	printf("node  ");
268: 	for (i = 0; i <= maxnode; i++)
269: 		if (numa_bitmask_isbitset(numa_nodes_ptr, i))
270: 			printf("% 4d ", i);
271: 	printf("\n");
272: 	for (i = 0; i <= maxnode; i++) {
273: 		if (!numa_bitmask_isbitset(numa_nodes_ptr, i))
274: 			continue;
275: 		printf("% 4d: ", i);
276: 		for (k = 0; k <= maxnode; k++)
277: 			if (numa_bitmask_isbitset(numa_nodes_ptr, i) &&
278: 			    numa_bitmask_isbitset(numa_nodes_ptr, k))
279: 				printf("% 4d ", numa_distance(i,k));
280: 		printf("\n");
281: 	}
282: }
