284: static void print_node_cpus(int node)
285: {
286:         int i = 0, err, start, segment = 0, count = 0;
287:         struct bitmask *cpus;
288: 
289:         cpus = numa_allocate_cpumask();
290:         err = numa_node_to_cpus(node, cpus);
291:         if (err < 0) {
292:                 goto out;
293:         }
294: 
295:         while (i < cpus->size) {
296:                 if (!cpu_compress) {
297:                         if (numa_bitmask_isbitset(cpus, i))
298:                         printf(" %d", i);
299:                         i++;
300:                         continue;
301:                 }
302: 
303:                 start = -1;
304: 
305:                 // Find the start and end of a range of available CPUs.
306:                 while (i < cpus->size && numa_bitmask_isbitset(cpus, i)) {
307:                         if (start == -1) start = i;
308:                         i++;
309:                 }
310:                 if (start == -1) {
311:                         i++;
312:                         continue;
313:                 }
314:                 if (segment) {
315:                         printf(",");
316:                 }
317: 
318:                 int end = i - 1;
319:                 count += (end - start) + 1;
320:                 if (start == end) {
321:                         printf(" %d", start);
322:                 } else {
323:                         printf(" %d-%d", start, end);
324:                 }
325:                 segment++;
326:         }
327: 
328:         if (!cpu_compress)
329:                 printf("\n");
330:         else
331:                 printf(" (%d)\n", count);
332: 
333: out:
334:         numa_free_cpumask(cpus);
335: }
