337: static void hardware(void)
338: {
339: 	int i;
340: 	int numnodes=0;
341: 	int prevnode=-1;
342: 	int skip=0;
343: 	int maxnode = numa_max_node();
344: 
345: 	if (numa_available() < 0) {
346:                 printf("No NUMA available on this system\n");
347:                 exit(1);
348:         }
349: 
350: 	for (i=0; i<=maxnode; i++)
351: 		if (numa_bitmask_isbitset(numa_nodes_ptr, i))
352: 			numnodes++;
353: 	printf("available: %d nodes (", numnodes);
354: 	for (i=0; i<=maxnode; i++) {
355: 		if (numa_bitmask_isbitset(numa_nodes_ptr, i)) {
356: 			if (prevnode == -1) {
357: 				printf("%d", i);
358: 				prevnode=i;
359: 				continue;
360: 			}
361: 
362: 			if (i > prevnode + 1) {
363: 				if (skip) {
364: 					printf("%d", prevnode);
365: 					skip=0;
366: 				}
367: 				printf(",%d", i);
368: 				prevnode=i;
369: 				continue;
370: 			}
371: 
372: 			if (i == prevnode + 1) {
373: 				if (!skip) {
374: 					printf("-");
375: 					skip=1;
376: 				}
377: 				prevnode=i;
378: 			}
379: 
380: 			if ((i == maxnode) && skip)
381: 				printf("%d", prevnode);
382: 		}
383: 	}
384: 	printf(")\n");
385: 
386: 	for (i = 0; i <= maxnode; i++) {
387: 		char buf[64];
388: 		long long fr;
389: 		unsigned long long sz = numa_node_size64(i, &fr);
390: 		if (!numa_bitmask_isbitset(numa_nodes_ptr, i))
391: 			continue;
392: 
393: 		printf("node %d cpus:", i);
394: 		print_node_cpus(i);
395: 		printf("node %d size: %s\n", i, fmt_mem(sz, buf));
396: 		printf("node %d free: %s\n", i, fmt_mem(fr, buf));
397: 	}
398: 	print_distances(maxnode);
399: }
