494: static struct bitmask *numactl_parse_nodestring(char *s, int flag)
495: {
496: 	static char *last;
497: 
498: 	if (s[0] == 's' && !strcmp(s, "same")) {
499: 		if (!last)
500: 			usage_msg("same needs previous node specification");
501: 		s = last;
502: 	} else {
503: 		last = s;
504: 	}
505: 
506: 	if (flag == ALL)
507: 		return numa_parse_nodestring_all(s);
508: 	else
509: 		return numa_parse_nodestring(s);
510: }
