512: int main(int ac, char **av)
513: {
514: 	int c;
515: 	char *end;
516: 	char shortopts[array_len(opts)*2 + 1];
517: 	struct bitmask *mask = NULL;
518: 	int did_cpubind = 0;
519: 	int did_strict = 0;
520: 	int do_shm = 0;
521: 	int do_dump = 0;
522: 	int parse_all = 0;
523: 	int numa_balancing = 0;
524: 	int do_hardware = 0;
525: 	int weighted_interleave = 0;
526: 
527: 	get_short_opts(opts,shortopts);
528: 	while ((c = getopt_long(ac, av, shortopts, opts, NULL)) != -1) {
529: 		switch (c) {
530: 		case 's': /* --show */
531: 			show();
532: 			exit(0);
533: 		case 'H': /* --hardware */
534: 			nopolicy();
535: 			do_hardware = 1;
536: 			break;
537: 		case 'b': /* --balancing  */
538: 			nopolicy();
539: 			numa_balancing = 1;
540: 			break;
541: 		case 'w': /* --weighted-interleave */
542: 			weighted_interleave = 1;
543: 			/* fall-through - logic is the same as interleave */
544: 		case 'i': /* --interleave */
545: 			checknuma();
546: 			if (parse_all)
547: 				mask = numactl_parse_nodestring(optarg, ALL);
548: 			else
549: 				mask = numactl_parse_nodestring(optarg, CPUSET);
550: 			if (!mask) {
551: 				printf ("<%s> is invalid\n", optarg);
552: 				usage();
553: 			}
554: 
555: 			errno = 0;
556: 			did_node_cpu_parse = 1;
557: 			if (weighted_interleave)
558: 				setpolicy(MPOL_WEIGHTED_INTERLEAVE);
559: 			else
560: 				setpolicy(MPOL_INTERLEAVE);
561: 			if (shmfd >= 0)
562: 				numa_interleave_memory(shmptr, shmlen, mask);
563: 			else {
564: 				if (weighted_interleave)
565: 					numa_set_weighted_interleave_mask(mask);
566: 				else
567: 					numa_set_interleave_mask(mask);
568: 			}
569: 			checkerror("setting interleave mask");
570: 			break;
571: 		case 'N': /* --cpunodebind */
572: 		case 'c': /* --cpubind */
573: 			dontshm("-c/--cpubind/--cpunodebind");
574: 			checknuma();
575: 			if (parse_all)
576: 				mask = numactl_parse_nodestring(optarg, ALL);
577: 			else
578: 				mask = numactl_parse_nodestring(optarg, CPUSET);
579: 			if (!mask) {
580: 				printf ("<%s> is invalid\n", optarg);
581: 				usage();
582: 			}
583: 			errno = 0;
584: 			check_cpubind(do_shm);
585: 			did_cpubind = 1;
586: 			did_node_cpu_parse = 1;
587: 			numa_run_on_node_mask_all(mask);
588: 			checkerror("sched_setaffinity");
589: 			break;
590: 		case 'C': /* --physcpubind */
591: 		{
592: 			struct bitmask *cpubuf;
593: 			dontshm("-C/--physcpubind");
594: 			if (parse_all)
595: 				cpubuf = numa_parse_cpustring_all(optarg);
596: 			else
597: 				cpubuf = numa_parse_cpustring(optarg);
598: 			if (!cpubuf) {
599: 				printf ("<%s> is invalid\n", optarg);
600: 				usage();
601: 			}
602: 			errno = 0;
603: 			check_cpubind(do_shm);
604: 			did_cpubind = 1;
605: 			did_node_cpu_parse = 1;
606: 			numa_sched_setaffinity(0, cpubuf);
607: 			checkerror("sched_setaffinity");
608: 			numa_bitmask_free(cpubuf);
609: 			break;
610: 		}
611: 		case 'm': /* --membind */
612: 			checknuma();
613: 			setpolicy(MPOL_BIND);
614: 			if (parse_all)
615: 				mask = numactl_parse_nodestring(optarg, ALL);
616: 			else
617: 				mask = numactl_parse_nodestring(optarg, CPUSET);
618: 			if (!mask) {
619: 				printf ("<%s> is invalid\n", optarg);
620: 				usage();
621: 			}
622: 			errno = 0;
623: 			did_node_cpu_parse = 1;
624: 			numa_set_bind_policy(1);
625: 			if (shmfd >= 0) {
626: 				numa_tonodemask_memory(shmptr, shmlen, mask);
627: 			} else if (numa_balancing) {
628: 				numa_set_membind_balancing(mask);
629: 			} else {
630: 				numa_set_membind(mask);
631: 			}
632: 			numa_set_bind_policy(0);
633: 			checkerror("setting membind");
634: 			break;
635: 		case 'P': /* --preferred-many */
636: 			if (!numa_has_preferred_many())
637: 				complain("preferred-many requested without kernel support");
638: 		case 'p': /* --preferred */
639: 			checknuma();
640: 			if (parse_all)
641: 				mask = numactl_parse_nodestring(optarg, ALL);
642: 			else
643: 				mask = numactl_parse_nodestring(optarg, CPUSET);
644: 			if (!mask) {
645: 				printf ("<%s> is invalid\n", optarg);
646: 				usage();
647: 			}
648: 			errno = 0;
649: 			did_node_cpu_parse = 1;
650: 			numa_set_bind_policy(0);
651: 			if (shmfd >= 0) {
652: 				numa_tonode_memory(shmptr, shmlen, find_first(mask));
653: 				/* Correspond to numa_set_bind_policy function */
654: 				if (numa_has_preferred_many()) {
655: 					setpolicy(MPOL_PREFERRED_MANY);
656: 				} else {
657: 					setpolicy(MPOL_PREFERRED);
658: 				}
659: 			} else if (c == 'p') {
660: 				if (numa_bitmask_weight(mask) != 1)
661: 					usage();
662: 
663: 				setpolicy(MPOL_PREFERRED);
664: 				numa_set_preferred(find_first(mask));
665: 			} else {
666: 				setpolicy(MPOL_PREFERRED_MANY);
667: 				numa_set_preferred_many(mask);
668: 			}
669: 			checkerror("setting preferred node");
670: 			break;
671: 		case 'l': /* --local */
672: 			checknuma();
673: 			setpolicy(MPOL_LOCAL);
674: 			errno = 0;
675: 			if (shmfd >= 0)
676: 				numa_setlocal_memory(shmptr, shmlen);
677: 			else
678: 				numa_set_localalloc();
679: 			checkerror("local allocation");
680: 			break;
681: 		case 'S': /* --shm */
682: 			check_cpubind(did_cpubind);
683: 			nopolicy();
684: 			attach_sysvshm(optarg, "--shm");
685: 			shmattached = 1;
686: 			break;
687: 		case 'f': /* --file */
688: 			check_cpubind(did_cpubind);
689: 			nopolicy();
690: 			attach_shared(optarg, "--file");
691: 			shmattached = 1;
692: 			break;
693: 		case 'L': /* --length */
694: 			noshm("--length");
695: 			shmlen = memsize(optarg);
696: 			break;
697: 		case 'M': /* --shmmode */
698: 			noshm("--shmmode");
699: 			shmmode = strtoul(optarg, &end, 8);
700: 			if (end == optarg || *end)
701: 				usage();
702: 			break;
703: 		case 'd': /* --dump */
704: 			if (shmfd < 0)
705: 				complain(
706: 				"Cannot do --dump without shared memory.\n");
707: 			dump_shm();
708: 			do_dump = 1;
709: 			break;
710: 		case 'D': /* --dump-nodes */
711: 			if (shmfd < 0)
712: 				complain(
713: 			    "Cannot do --dump-nodes without shared memory.\n");
714: 			dump_shm_nodes();
715: 			do_dump = 1;
716: 			break;
717: 		case 't': /* --strict */
718: 			did_strict = 1;
719: 			numa_set_strict(1);
720: 			break;
721: 		case 'I': /* --shmid */
722: 			shmid = strtoul(optarg, &end, 0);
723: 			if (end == optarg || *end)
724: 				usage();
725: 			break;
726: 
727: 		case 'u': /* --huge */
728: 			noshm("--huge");
729: 			shmflags |= SHM_HUGETLB;
730: 			break;
731: 
732: 		case 'o':  /* --offset */
733: 			noshm("--offset");
734: 			shmoffset = memsize(optarg);
735: 			break;
736: 
737: 		case 'T': /* --touch */
738: 			needshm("--touch");
739: 			check_shmbeyond("--touch");
740: 			numa_police_memory(shmptr, shmlen);
741: 			break;
742: 
743: 		case 'V': /* --verify */
744: 			needshm("--verify");
745: 			if (set_policy < 0)
746: 				complain("Need a policy first to verify");
747: 			check_shmbeyond("--verify");
748: 			numa_police_memory(shmptr, shmlen);
749: 			if (!mask)
750: 				complain("Need a mask to verify");
751: 			else
752: 				verify_shm(set_policy, mask);
753: 			break;
754: 
755: 		case 'a': /* --all */
756: 			check_all_parse(did_node_cpu_parse);
757: 			parse_all = 1;
758: 			break;
759: 		case CPU_COMPRESS:
760: 			cpu_compress = 1;
761: 			break;
762: 		case OPT_VERSION:
763: 			nopolicy();
764: 			printf("%s\n", VERSION);
765: 			exit(0);
766: 		default:
767: 			usage();
768: 		}
769: 	}
770: 
771: 	if (do_hardware) {
772: 		hardware();
773: 		exit(0);
774: 	}
775: 
776: 	numa_bitmask_free(mask);
777: 
778: 	av += optind;
779: 
780: 	if (shmfd >= 0) {
781: 		if (*av)
782: 			usage();
783: 		exit(exitcode);
784: 	}
785: 
786: 	if (did_strict)
787: 		fprintf(stderr,
788: 			"numactl: warning. Strict flag for process ignored.\n");
789: 
790: 	if (do_dump)
791: 		usage_msg("cannot do --dump|--dump-shm for process");
792: 
793: 	if (shmoption)
794: 		usage_msg("shm related option %s for process", shmoption);
795: 
796: 	if (*av == NULL)
797: 		usage();
798: 	execvp(*av, av);
799: 	complain("execution of `%s': %s\n", av[0], strerror(errno));
800: 	return 0; /* not reached */
801: }

