47: static long huge_page_size(void)
48: {
49: 	size_t len = 0;
50: 	long huge_size = 0;
51: 	char *line = NULL;
52: 	FILE *f = fopen("/proc/meminfo", "r");
53: 	if (f != NULL) {
54: 		while (getdelim(&line, &len, '\n', f) > 0) {
55: 			int ps;
56: 			if (sscanf(line, "Hugepagesize: %d kB", &ps) == 1) {
57: 				huge_size = ps * 1024;
58: 				break;
59: 			}
60: 		}
61: 		free(line);
62: 		fclose(f);
63: 	}
64: 	return huge_size ? huge_size : getpagesize();
65: }
