67: static void check_region(char *opt)
68: {
69: 	if (((unsigned long)shmptr % shm_pagesize) || (shmlen % shm_pagesize)) {
70: 		fprintf(stderr, "numactl: policy region not page aligned\n");
71: 		exit(1);
72: 	}
73: 	if (!shmlen) {
74: 		fprintf(stderr,
75: 		"numactl: policy region length not specified before %s\n",
76: 			opt);
