81: static key_t sysvkey(char *name)
82: {
83: 	int fd;
84: 	key_t key = ftok(name, shmid);
85: 	if (key >= 0)
86: 		return key;
87: 
88: 	fprintf(stderr, "numactl: Creating shm key file %s mode %04o\n",
89: 		name, shmmode);
90: 	fd = creat(name, shmmode);
91: 	if (fd < 0)
92: 		nerror("cannot create key for shm %s\n", name);
93: 	key = ftok(name, shmid);
94: 	if (key < 0)
95: 		nerror("cannot get key for newly created shm key file %s",
96: 		       name);
97: 	return key;
