100: /* Attach a sysv style shared memory segment. */
101: void attach_sysvshm(char *name, char *opt)
102: {
103: 	struct shmid_ds s;
104: 	key_t key = sysvkey(name);
105: 
106: 	shmfd = shmget(key, shmlen, shmflags);
107: 	if (shmfd < 0 && errno == ENOENT) {
108: 		if (shmlen == 0)
109: 			complain(
110:                      "need a --length to create a sysv shared memory segment");
111: 		fprintf(stderr,
112:          "numactl: Creating shared memory segment %s id %ld mode %04o length %.fMB\n",
113: 			name, shmid, shmmode, ((double)(shmlen + shmoffset)) / (1024*1024) );
114: 		shmfd = shmget(key, shmlen + shmoffset, IPC_CREAT|shmmode|shmflags);
115: 		if (shmfd < 0)
116: 			nerror("cannot create shared memory segment");
117: 	}
118: 
119: 	if (shmlen == 0) {
120: 		if (shmctl(shmfd, IPC_STAT, &s) < 0)
121: 			err("shmctl IPC_STAT");
122: 		shmlen = s.shm_segsz;
123: 	}
124: 
125: 	shmptr = shmat(shmfd, NULL, 0);
126: 	if (shmptr == (void*)-1)
127: 		err("shmat");
128: 	shmptr += shmoffset;
129: 
130: 	shm_pagesize = (shmflags & SHM_HUGETLB) ? huge_page_size() : getpagesize();
131: 
132: 	check_region(opt);
133: }
