135: /* Attach a shared memory file. */
136: void attach_shared(char *name, char *opt)
137: {
138: 	struct stat st;
139: 
140: 	shmfd = open(name, O_RDWR);
141: 	if (shmfd < 0) {
142: 		errno = 0;
143: 		if (shmlen == 0)
144: 		        complain("need a --length to create a shared file");
145: 		shmfd = open(name, O_RDWR|O_CREAT, shmmode);
146: 		if (shmfd < 0)
147: 			nerror("cannot create file %s", name);
148: 	}
149: 	if (fstat(shmfd, &st) < 0)
150: 		err("shm stat");
151: 	/* the file size must be larger than mmap shmlen + shmoffset, otherwise SIGBUS
152: 	 * will be caused when we access memory, because mmaped memory is no longer in
153: 	 * the range of the file laster.
154: 	 */
155: 	if ((shmlen + shmoffset) > st.st_size) {
156: 		if (ftruncate(shmfd, shmlen + shmoffset) < 0) {
157: 			/* XXX: we could do it by hand, but it would it
158: 			   would be impossible to apply policy then.
159: 			   need to fix that in the kernel. */
160: 			perror("ftruncate");
161: 			exit(1);
162: 		}
163: 	}
164: 
165: 	shm_pagesize = st.st_blksize;
166: 
167: 	check_region(opt);
168: 
169: 	/* RED-PEN For shmlen > address space may need to map in pieces.
170: 	   Left for some poor 32bit soul. */
171: 	shmptr = mmap(NULL, shmlen, PROT_READ | PROT_WRITE, MAP_SHARED, shmfd, shmoffset);
172: 	if (shmptr == (char*)-1)
173: 		err("shm mmap");
174: }
