188: /* Dump policies in a shared memory segment. */
189: void dump_shm(void)
190: {
191: 	struct bitmask *nodes, *prevnodes, *tag;
192: 	int prevpol = -1, pol;
193: 	unsigned long long c, start;
194: 
195: 	start = 0;
196: 	if (shmlen == 0) {
197: 		printf("nothing to dump\n");
198: 		return;
199: 	}
200: 
201: 	nodes = numa_allocate_nodemask();
202: 	tag = prevnodes = numa_allocate_nodemask();
203: 
204: 	for (c = 0; c < shmlen; c += shm_pagesize) {
205: 		if (get_mempolicy(&pol, nodes->maskp, nodes->size, c+shmptr,
206: 						MPOL_F_ADDR) < 0)
207: 			err("get_mempolicy on shm");
208: 		if (pol == prevpol && numa_bitmask_equal(prevnodes, nodes))
209: 			continue;
210: 		if (prevpol != -1)
211: 			dumppol(start, c, prevpol, prevnodes);
212: 
213: 		copy_bitmask_to_bitmask(nodes, prevnodes);
214: 		prevpol = pol;
215: 		start = c;
216: 	}
217: 	dumppol(start, c, prevpol, prevnodes);
218: 	numa_free_nodemask(nodes);
219: 	numa_free_nodemask(tag);
220: }
