235: 		printf("nothing to dump\n");
236: 		return;
237: 	}
238: 
239: 	for (c = 0; c < shmlen; c += shm_pagesize) {
240: 		if (get_mempolicy(&node, NULL, 0, c+shmptr,
241: 						MPOL_F_ADDR|MPOL_F_NODE) < 0)
242: 			err("get_mempolicy on shm");
243: 		if (node == prevnode)
244: 			continue;
245: 		if (prevnode != -1)
246: 			dumpnode(start, c, prevnode);
