264: static unsigned interleave_next(unsigned cur, struct bitmask *mask)
265: {
266: 	int numa_num_nodes = numa_num_possible_nodes();
267: 
268: 	++cur;
269: 	while (!numa_bitmask_isbitset(mask, cur)) {
270: 		cur = (cur+1) % numa_num_nodes;
271: 	}
272: 	return cur;
273: }
