275: /* Verify policy in a shared memory segment */
276: void verify_shm(int policy, struct bitmask *nodes)
277: {
278: 	char *p;
279: 	int ilnode, node;
280: 	int pol2;
281: 	struct bitmask *nodes2;
282: 
283: 	if (policy == MPOL_INTERLEAVE) {
284: 		if (get_mempolicy(&ilnode, NULL, 0, shmptr,
285: 					MPOL_F_ADDR|MPOL_F_NODE)
286: 		    < 0)
287: 			err("get_mempolicy");
288: 	}
289: 
290: 	nodes2 = numa_allocate_nodemask();
291: 
292: 	for (p = shmptr; p - (char *)shmptr < shmlen; p += shm_pagesize) {
293: 		if (get_mempolicy(&pol2, nodes2->maskp, nodes2->size, p,
294: 							MPOL_F_ADDR) < 0)
295: 			err("get_mempolicy");
296: 		if (pol2 != policy) {
297: 			vwarn(p, "wrong policy %s, expected %s\n",
298: 			      policy_name(pol2), policy_name(policy));
299: 			goto out;
300: 		}
301: 		if (memcmp(nodes2->maskp, nodes->maskp, numa_bitmask_nbytes(nodes))) {
302: 			vwarn(p, "mismatched node mask\n");
303: 			printmask("expected", nodes);
304: 			printmask("real", nodes2);
305: 		}
306: 
307: 		if (get_mempolicy(&node, NULL, 0, p, MPOL_F_ADDR|MPOL_F_NODE) < 0)
308: 			err("get_mempolicy");
309: 
310: 		switch (policy) {
311: 		case MPOL_INTERLEAVE:
312: 			if (node < 0 || !numa_bitmask_isbitset(nodes2, node))
313: 				vwarn(p, "interleave node out of range %d\n", node);
314: 			if (node != ilnode) {
315: 				vwarn(p, "expected interleave node %d, got %d\n",
316: 				     ilnode,node);
317: 				goto out;
318: 			}
319: 			ilnode = interleave_next(ilnode, nodes2);
320: 			break;
321: 		case MPOL_PREFERRED_MANY:
322: 		case MPOL_PREFERRED:
323: 		case MPOL_BIND:
324: 			if (!numa_bitmask_isbitset(nodes2, node)) {
325: 				vwarn(p, "unexpected node %d\n", node);
326: 				printmask("expected", nodes2);
327: 			}
328: 			break;
329: 
330: 		case MPOL_DEFAULT:
331: 			break;
332: 		}
333: 	}
334: 
335: out:
336: 	numa_free_nodemask(nodes2);
337: }

