{"type":"tool_use","timestamp":1783787755934,"sessionID":"ses_0adfa04c0ffe7T9U2aBhrqlgzw","part":{"type":"tool","tool":"write","callID":"call_7d7da8a8ee914b36af520a3c","state":{"status":"completed","input":{"filePath":"runs\pc-lib-3456\numactl\2026-07-11T15-46-32-656Z\blocks\function_summary.json","content":"{
  "summary": "numactl 是一套 Linux NUMA（非一致内存访问）策略控制工具集，包含命令行工具 numactl 和共享库 libnuma。numactl 允许用户以指定的 NUMA 策略（如节点绑定、内存交错分配、CPU 亲和性）启动其他程序；libnuma 则为应用程序提供 C API，使程序可在运行时设置和查询 NUMA 内存分配策略与 CPU 绑定。面向系统管理员和需要精细控制 NUMA 拓扑的高性能 C/C++ 应用开发者。",
  "categories": [
    {
      "name": "NUMA 内存策略控制",
      "description": "设置和查询进程的 NUMA 内存分配策略，包括节点绑定（membind）、交错分配（interleave/weighted interleave）、优先节点分配（preferred）和本地分配（localalloc），策略可作用于整个进程或特定虚拟地址区域。",
      "evidence": ["libnuma.c:set_mempolicy", "libnuma.c:mbind", "libnuma.c:numa_set_membind", "libnuma.c:numa_set_interleave_mask", "numactl.c:parse_policy"]
    },
    {
      "name": "NUMA 拓扑查询",
      "description": "查询系统 NUMA 拓扑信息，包括可用节点数、节点内存大小/空闲量、节点间距离矩阵（SLIT）、CPU 到节点的映射关系，数据来源于 /sys/devices/system/node 和 /proc/self/status。",
      "evidence": ["libnuma.c:numa_max_node", "libnuma.c:numa_node_size64", "libnuma.c:numa_num_configured_nodes", "distance.c:numa_distance", "sysfs.c:sysfs_node_read"]
    },
    {
      "name": "CPU 亲和性绑定",
      "description": "将进程/线程绑定到指定 NUMA 节点对应的 CPU 集合上运行，通过 sched_setaffinity/sched_getaffinity 系统调用实现，支持节点范围、CPU 列表和 cpuset 相对偏移等灵活指定方式。",
      "evidence": ["libnuma.c:numa_run_on_node", "libnuma.c:numa_run_on_node_mask", "libnuma.c:numa_sched_setaffinity", "affinity.c:affinity_class", "numactl.c:show_physcpubind"]
    },
    {
      "name": "IO 设备亲和性解析",
      "description": "根据网络设备名、块设备名、IP 地址或 PCI 设备地址解析出对应的 NUMA 节点归属，通过 rtnetlink 查询路由表获取网络设备所属节点，或通过 /sys/class 下的设备 sysfs 链接读取 numa_node 属性。",
      "evidence": ["affinity.c:affinity_class", "affinity.c:affinity_ip", "affinity.c:affinity_pci", "rtnetlink.c:rtnetlink_request"]
    },
    {
      "name": "共享内存策略管理",
      "description": "对基于 SysV shm 或 tmpfs 文件映射的共享内存区域设置 NUMA 内存策略，支持策略的查询（dump）和校验（verify），确保共享内存段的页面分配符合预期 NUMA 策略。",
      "evidence": ["shm.c:attach_sysvshm", "shm.c:attach_shared", "shm.c:dump_shm", "shm.c:verify_shm", "numactl.c:dump_shm_nodes"]
    }
  ],
  "domain": "系统软件/高性能计算",
  "target_users": "Linux 系统管理员、HPC 应用开发者、需要 NUMA 优化的 C/C++ 程序开发者",
  "ecosystem": "cpp"
}
